        const required = defs.crops[ui.seed]?.required_crop_structure_id;
        const valid = ui.mode === "plant" ? kind === "land" && c.tilled && !c.crop && (!required || c.cropStructure === required) : ui.mode === "build" ? !buildReason(c, ui.build) : false;
