        action = `<button class="au-secondary" data-action="${c.tilled ? "plant-mode" : "till"}">${ico("seed")}<span>${c.tilled ? "选择种子" : "开垦土地"}</span></button><button class="au-secondary" data-mode="build">${ico("tool")}<span>营建设施</span></button>`;
